            @RequestHeader(name = "X-User", required = false) String userHeader,
            @RequestParam(name = "reason", required = false) String reason,
            @RequestParam(name = "batch", required = false) String batch) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
        return run(action, claim, repository, entityManager, people, rates, grades, periods, sheet, roles, log, voidReasons,
                userHeader, reason, batch, false);
    }

    /** The change itself; on a dry run (a settle only) it refuses what the settle would refuse and changes nothing. */
    static String run(String action, Claim claim, ClaimRepository repository,
            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
            Sheet sheet, RoleRepository roles, ClaimLogRepository log, VoidReasonRepository voidReasons,
            String userHeader, String reason, String batch, boolean dryRun) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
        if (dryRun && !"settle".equals(action)) {
            throw new ClaimStatusException("Only a settle can be checked.");
        }
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot change status.");
        }
        String role = roles.roleOf(claim.getSheetId(), user);
        if (("open".equals(action) || "settle".equals(action) || "void".equals(action)) && !sheet.allows(action, role)) {
            throw new ClerkLimitException("A " + role + " cannot " + action + " a claim.");
        }
        if ("open".equals(action) && claim.getStatus().after(action) != null) {
            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
            boolean perPeriod = sheet.periodNumberingOn();
            if (perPeriod) {
                repository.lockSheet(claim.getSheetId());
            } else {
                repository.takeNextNumber(claim.getSheetId());
            }
            entityManager.refresh(claim);
            ClaimStatus next = check(claim, action);
            BigDecimal noteThreshold = sheet.noteThresholdOn(claim.getDate());
            if (noteThreshold != null && (claim.getNote() == null || claim.getNote().isBlank())) {
                BigDecimal due = people.findById(claim.getPersonId())
                        .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                                grades.gradesOf(p), sheet).due(claim))
                        .orElse(null);
                if (due != null && due.compareTo(noteThreshold) > 0) {
                    throw new ClaimStatusException("A claim whose due is above the note threshold needs a note to be opened.");
                }
            }
            if (perPeriod) {
                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                        .filter(p -> p.contains(claim.getDueBy())).map(Period::getName).findFirst().orElse(null);
                String seq = prefix == null ? "X" : "P:" + prefix;
                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
            } else {
                claim.setNumber(String.valueOf(repository.lastNumber(claim.getSheetId())));
            }
            claim.setStatus(next);
            claim.setOpenedBy(user);
        } else {
            ClaimStatus next = check(claim, action);
            boolean steward = Role.STEWARD.equals(role);
            if (("approve".equals(action) || "reject".equals(action)) && !steward) {
                throw new ClerkLimitException("Only a steward can approve or reject a pending claim.");
            }
            if ("void".equals(action) && claim.getStatus() == ClaimStatus.SETTLED) {
                if (!steward) {
                    throw new ClerkLimitException("Only a steward can void a settled claim.");
                }
                LocalDate settled = log.settledOn(claim);
                if (settled == null || sheet.getToday().isAfter(settled.plusDays(VOID_DAYS))) {
                    throw new ClaimStatusException("A settled claim can be voided only within " + VOID_DAYS + " days of its settlement.");
                }
            }
            if ("void".equals(action) && voidReasons.existsBySheetId(claim.getSheetId())) {
                String chosen = reason == null ? "" : reason.trim();
                if (chosen.isEmpty() || !voidReasons.existsBySheetIdAndReason(claim.getSheetId(), chosen)) {
                    throw new ClaimStatusException("A void needs a reason from the sheet's list.");
                }
                claim.setVoidReason(chosen);
            }
            if ("reject".equals(action) && (reason == null || reason.isBlank())) {
                throw new ClaimStatusException("A rejection needs a reason.");
            }
            if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
                throw new ClaimStatusException("A deferred claim cannot be settled until the sheet's today reaches its date.");
            }
            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
                throw new ClaimStatusException("The one who opened a claim cannot settle or approve it.");
            }
            if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
                throw new ClaimStatusException("The one who last edited a claim cannot settle or approve it.");
            }
            if (next == ClaimStatus.SETTLED) {
                PersonGrades personGrades = people.findById(claim.getPersonId()).map(grades::gradesOf).orElse(null);
                BigDecimal due = personGrades == null ? null
                        : new ClaimFigures(rates.findInChain(claim.getSheetId()),
                                personGrades, sheet).due(claim);
                BigDecimal threshold = sheet.proofThresholdFor(
                        personGrades == null ? null : personGrades.on(claim.getDate()), claim.getDate());
                if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                    throw new ProofRequiredException("A claim whose due is above the proof threshold needs a proof to be settled or approved.");
                }
                if (dryRun) {
                    return claim.getNumber();
                }
                BigDecimal limit = sheet.getClerkLimit();
                if ("settle".equals(action) && limit != null && due != null && due.compareTo(limit) > 0 && !steward) {
                    next = ClaimStatus.PENDING;
                } else {
                    claim.setDue(due);
                }
                if ("settle".equals(action)) {
                    String key = batch == null ? "" : batch.trim();
                    claim.setSettleBatch(key.isEmpty() ? null : repository.batchFor(claim.getSheetId(), key));
                }
            }
            claim.setStatus(next);
        }
        repository.saveAndFlush(claim);
        return claim.getNumber();
    }

    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
        ClaimStatus next = claim.getStatus().after(action);
        if (next == null) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
        }
        return next;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** One line of a claim's status log: a status it entered, who made the change, the sheet's today then and the
 * claim's due as it was worked out at that moment (null: n/a). */
@Entity
@Table(name = "claim_log")
public class ClaimLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    @Column(nullable = false)
    private String status;

    @Column(name = "by_user", nullable = false)
    private String byUser;

    @Column(name = "on_date", nullable = false)
    private LocalDate onDate;

    @Column(precision = 19, scale = 2)
    private BigDecimal due;

    protected ClaimLog() {
    }

    public ClaimLog(Claim claim, String byUser, LocalDate onDate, BigDecimal due) {
        this.sheetId = claim.getSheetId();
        this.claimId = claim.getId();
        this.status = claim.getStatus().name();
        this.byUser = byUser;
        this.onDate = onDate;
        this.due = due;
    }

    public Long getClaimId() {
        return claimId;
    }

    public String getStatus() {
        return status;
    }

    public LocalDate getOnDate() {
        return onDate;
    }

    /** The claim's due as it was worked out then (null: n/a); a SETTLED line's is the due it was settled at. */
    public BigDecimal getDue() {
        return due;
    }

    /** The line as the screen shows it: <STATUS> by <user> on <date> due=<due>. */
    public String line() {
        return status + " by " + byUser + " on " + onDate + " due=" + (due == null ? "n/a" : due.setScale(2).toPlainString());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in the order they are listed: newest first, a moved claim as its new person's newest. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    /** The sheet's claims some open editor locks. */
    List<Claim> findBySheetIdAndLockedByIsNotNull(String sheetId);

    /** Lists the claim as the newest: gives it the next listing key. */
    @Modifying
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
    int relist(@Param("id") Long id);

    /** The person's claims, newest first. */
    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The person's claims given this number (at most one: numbers are never reused on a sheet). */
    List<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** Refuses a correction unless the claim it corrects is a SETTLED claim of the same person; gives that
     *  claim's date (null when it is not a correction). */
    default LocalDate checkCorrects(String sheetId, Long personId, String corrects) throws InvalidClaimException {
        if (corrects == null) {
            return null;
        }
        return findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects).stream()
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).map(Claim::getDate).findFirst()
                .orElseThrow(() -> new InvalidClaimException("A correction must name a settled claim of the same person."));
    }

    /** Whether a claim on the sheet other than the given one (null: none) has the reference, ignoring case. */
    boolean existsBySheetIdAndRefIgnoreCaseAndIdNot(String sheetId, String ref, Long id);

    boolean existsBySheetIdAndRefIgnoreCase(String sheetId, String ref);

    /** Refuses a reference (null: none) another claim on the sheet already has, ignoring case. */
    default void checkRef(String sheetId, Long claimId, String ref) throws InvalidClaimException {
        if (ref == null) {
            return;
        }
        boolean used = claimId == null ? existsBySheetIdAndRefIgnoreCase(sheetId, ref)
                : existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, ref, claimId);
        if (used) {
            throw new InvalidClaimException("The reference " + ref + " is already used on this sheet.");
        }
    }

    /** Takes the sheet's next claim number; the update locks the sheet's row until the transaction ends, so
     * two claims opened at once are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :sheetId",
            nativeQuery = true)
    int takeNextNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastNumber(@Param("sheetId") String sheetId);

    /** Locks the sheet's row until the transaction ends without taking a number, so two claims opened at once in
     *  one per-period sequence are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :sheetId", nativeQuery = true)
    int lockSheet(@Param("sheetId") String sheetId);

    /** The last number given out in one of the sheet's per-period sequences; null when it has given none. */
    @Query(value = "SELECT last_number FROM claim_sequence WHERE sheet_id = :sheetId AND seq = :seq", nativeQuery = true)
    Integer lastInSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    @Modifying
    @Query(value = "INSERT INTO claim_sequence (sheet_id, seq, last_number) VALUES (:sheetId, :seq, 1)", nativeQuery = true)
    int startSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    @Modifying
    @Query(value = "UPDATE claim_sequence SET last_number = last_number + 1 WHERE sheet_id = :sheetId AND seq = :seq",
            nativeQuery = true)
    int advanceSequence(@Param("sheetId") String sheetId, @Param("seq") String seq);

    /** Takes the next number in one of the sheet's per-period sequences (from 1); call with the sheet locked. */
    default int takeNextInSequence(String sheetId, String seq) {
        Integer last = lastInSequence(sheetId, seq);
        if (last == null) {
            startSequence(sheetId, seq);
            return 1;
        }
        advanceSequence(sheetId, seq);
        return last + 1;
    }

    @Query(value = "SELECT batch_number FROM settle_batch WHERE sheet_id = :sheetId AND batch_key = :key", nativeQuery = true)
    Integer batchNumber(@Param("sheetId") String sheetId, @Param("key") String key);

    @Modifying
    @Query(value = "UPDATE sheet SET last_settle_batch = last_settle_batch + 1 WHERE id = :sheetId", nativeQuery = true)
    int takeNextBatch(@Param("sheetId") String sheetId);

    @Query(value = "SELECT last_settle_batch FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastBatch(@Param("sheetId") String sheetId);

    @Modifying
    @Query(value = "INSERT INTO settle_batch (sheet_id, batch_key, batch_number) VALUES (:sheetId, :key, :number)",
            nativeQuery = true)
    int startBatch(@Param("sheetId") String sheetId, @Param("key") String key, @Param("number") int number);

    /** The number of the bulk settle batch the key names: the sheet's next one the first time the key is used (a
     *  batch is numbered when its first claim settles). Locks the sheet's row first, so two batches numbered at once
     *  are numbered one after the other. */
    default int batchFor(String sheetId, String key) {
        lockSheet(sheetId);
        Integer number = batchNumber(sheetId, key);
        if (number != null) {
            return number;
        }
        takeNextBatch(sheetId);
        int next = lastBatch(sheetId);
        startBatch(sheetId, key, next);
        return next;
    }
}

