package net.officefloor.hq.app.sheet;


/** Loads the sheet by id, starting an empty one when the id was never used. */
public class LoadOrCreateSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheetOut) {
        String id = sheetId.trim();
        sheetOut.set(repository.findById(id).orElseGet(() -> repository.save(new Sheet(id))));
    }
}
package net.officefloor.hq.app.role;


/** The first step of every change: refuses it, before anything is read or written, when the signed-in name is a
 *  viewer on the sheet (a viewer sees everything and changes nothing). */
public class GuardViewer {
    public void guard(@PathVariable("sheetId") String sheetId,
            @RequestHeader(name = "X-User", required = false) String user, RoleRepository roles)
            throws ViewerRefusedException {
        if (Role.VIEWER.equals(roles.roleOf(sheetId, AuditUser.decode(user)))) {
            throw new ViewerRefusedException("A viewer cannot change anything on the sheet.");
        }
    }
}
package net.officefloor.hq.app.sheet;


/** The step after GuardViewer on every change: refuses it, before anything is read or written, when the sheet is
 *  archived (an archived sheet shows everything and changes nothing). */
public class GuardArchived {
    public void guard(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetArchivedException {
        if (repository.findById(sheetId.trim()).map(Sheet::isArchived).orElse(false)) {
            throw new SheetArchivedException("The sheet is archived: nothing on it can be changed.");
        }
    }
}
package net.officefloor.hq.app;


/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: they never carry the steward a delegate acts for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final ObjectProvider<RoleRepository> roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<RoleRepository> roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A record of a change made by a user
     *  name while the sheet's today is inside a delegation of the steward role to it ends with for=&lt;the steward
     *  who delegated&gt;. */
    public void record(String entry) {
        write(entry + forDelegator(entry));
    }

    /** " for=&lt;steward&gt;" when the record's by= acts for a steward on its sheet= today, else "". */
    private String forDelegator(String entry) {
        int space = entry.indexOf(' ');
        if (space < 0 || FIGURES.contains(entry.substring(0, space))) {
            return "";
        }
        String sheet = field(entry, "sheet");
        String by = field(entry, "by");
        if (sheet == null || by == null || by.isEmpty()) {
            return "";
        }
        String delegator = roles.getObject().delegatorOf(sheet, by);
        return delegator == null ? "" : " for=" + delegator;
    }

    private static String field(String entry, String name) {
        String key = " " + name + "=";
        int start = entry.indexOf(key);
        if (start < 0) {
            return null;
        }
        start += key.length();
        int end = entry.indexOf(' ', start);
        return end < 0 ? entry.substring(start) : entry.substring(start, end);
    }

    private synchronized void write(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Every line the file holds for a sheet (carrying sheet=&lt;id&gt;), in the order they were written. */
    public synchronized java.util.List<String> linesOf(String sheetId) {
        String token = "sheet=" + sheetId;
        try {
            if (!Files.exists(file)) {
                return java.util.List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream()
                    .filter(line -> java.util.Arrays.asList(line.split(" ")).contains(token))
                    .toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.person;


public class BuildPerson {
    public void build(@Val PersonRequest request, @Val Sheet sheet, PersonRepository repository,
            PersonAliasRepository aliases, Out<Person> personOut)
            throws InvalidPersonException {
        if (repository.existsBySheetIdAndNameIgnoreCase(sheet.getId(), request.name())
                || aliases.existsBySheetIdAndAliasIgnoreCase(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        if (request.contactOrNull() != null
                && repository.existsBySheetIdAndContact(sheet.getId(), request.contactOrNull())) {
            throw new InvalidPersonException("The contact is already in use on this sheet.");
        }
        Person person = new Person(sheet.getId(), request.name(), request.grade());
        person.setAddedOn(sheet.getToday());
        person.setTerms(request.termsDays());
        person.setContact(request.contactOrNull());
        personOut.set(repository.save(person));
    }
}
package net.officefloor.hq.app.person;


/** Records the added person, once it is saved, with their terms when they have any, and their contact when they have one. */
public class AuditPersonAdded {
    public void audit(@Val Person person, @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + AuditUser.decode(user)
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact()));
    }
}
